// The tools/list entries of the layout tools, as src/mcp.ts's JSON.stringify writes them (generated by testdata/genlistings.mjs; mcp_test.go compares).
var layoutListings = map[string]string{
	"layout_get":     "{\"name\":\"layout_get\",\"group\":\"layout\",\"description\":\"Read the human's web layout: each world's panes as an indented tree (tabs, which tab is active, which pane is focused), then the raw layout JSON with its version. Read it before you arrange anything. Use layout_arrange only when the human asked you to arrange their screen.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}}}",
	"layout_arrange": "{\"name\":\"layout_arrange\",\"group\":\"layout\",\"description\":\"Arrange the human's web layout (panes and tabs) with a batch of ops, applied all or none. Act only when the human asked you to arrange their screen (for example \\\"open my usage page beside this agent\\\"); never rearrange it on your own initiative. Read the layout first with layout_get, and pass its version as base so a change made meanwhile is refused (409) rather than overwritten. Tab keys name views: agent:ID (an agent's terminal), view:ID (stam's own conversation view of an agent), details:ID, instructions:ID, mail:ID (mail:human is the human's inbox), thread:ID (a mail thread), itsa:ID (an ITSA), board:ID or board:all (ITSA boards), shell:MACHINE:ID, config (Settings), usage. World: \\\"main\\\" is the layout's current world (or home when none is current): the world an agent last sent the human to, not necessarily what each device shows, since the human's own navigation stays on that device. A current op moves every device to its world; other worlds are named as the layout names them (agent IDs, t:THREAD, w:config, w:usage, w:itsa:ID). Returns the new layout as layout_get does. An invalid op or a stale base returns the error and changes nothing.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"base\":{\"type\":\"integer\",\"description\":\"The layout version you read with layout_get. A different current version is refused.\"},\"ops\":{\"type\":\"array\",\"description\":\"Applied in order.\",\"items\":{\"oneOf\":[{\"type\":\"object\",\"description\":\"open: show a tab in a world; splits beside pane, or adds to it. Opens in the background when background is true.\",\"required\":[\"op\",\"world\",\"key\"],\"properties\":{\"op\":{\"const\":\"open\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\",\"description\":\"A tab key such as agent:ID.\"},\"pane\":{\"type\":\"string\",\"description\":\"Pane to put it in (default: the focused pane).\"},\"split\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"],\"description\":\"Make a new pane beside the pane, on this side.\"},\"background\":{\"type\":\"boolean\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"close: remove a tab from its pane; an empty pane goes.\",\"required\":[\"op\",\"world\",\"key\"],\"properties\":{\"op\":{\"const\":\"close\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"swap: show a tab in place of another, in the same pane and place (an agent's terminal agent:ID and stam's view of it view:ID trade places); with, open elsewhere in the world, moves there.\",\"required\":[\"op\",\"world\",\"key\",\"with\"],\"properties\":{\"op\":{\"const\":\"swap\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"},\"with\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"move: move a tab to a pane, before a tab, or to a new pane on a side.\",\"required\":[\"op\",\"world\",\"key\",\"to\"],\"properties\":{\"op\":{\"const\":\"move\"},\"world\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"},\"to\":{\"type\":\"string\",\"description\":\"Target pane id.\"},\"before\":{\"type\":[\"string\",\"null\"],\"description\":\"Tab key to put it before.\"},\"side\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"]}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"split: make an empty pane beside a pane (or move its active tab into the new pane when it has several).\",\"required\":[\"op\",\"world\",\"pane\",\"side\"],\"properties\":{\"op\":{\"const\":\"split\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"side\":{\"enum\":[\"right\",\"left\",\"down\",\"up\"]}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"closePane: close a pane; its tabs join a neighbour.\",\"required\":[\"op\",\"world\",\"pane\"],\"properties\":{\"op\":{\"const\":\"closePane\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"activate: make a tab the active one in its pane.\",\"required\":[\"op\",\"world\",\"pane\",\"key\"],\"properties\":{\"op\":{\"const\":\"activate\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"focus: make a pane the focused one.\",\"required\":[\"op\",\"world\",\"pane\"],\"properties\":{\"op\":{\"const\":\"focus\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"tabBar: show or hide a pane's tab bar.\",\"required\":[\"op\",\"world\",\"pane\",\"on\"],\"properties\":{\"op\":{\"const\":\"tabBar\"},\"world\":{\"type\":\"string\"},\"pane\":{\"type\":\"string\"},\"on\":{\"type\":\"boolean\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"setRoot: replace a world's whole pane tree. root is a pane or a split node (id, split row|col, children, sizes; a pane has id, tabs, active).\",\"required\":[\"op\",\"world\",\"root\"],\"properties\":{\"op\":{\"const\":\"setRoot\"},\"world\":{\"type\":\"string\"},\"root\":{\"type\":\"object\"},\"focusKey\":{\"type\":\"string\",\"description\":\"Focus the pane holding this tab.\"}},\"additionalProperties\":false},{\"type\":\"object\",\"description\":\"current: send the human to a world: every device switches to it, and it becomes the one \\\"main\\\" names; null for home.\",\"required\":[\"op\",\"world\"],\"properties\":{\"op\":{\"const\":\"current\"},\"world\":{\"type\":[\"string\",\"null\"]}},\"additionalProperties\":false}]}}},\"required\":[\"ops\"]}}",
}
